import Link from "next/link";

const samplePhotos=[
  {id:"1",src:"https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&w=1200&q=80",alt:"Outdoor Portland wedding ceremony"},
  {id:"2",src:"https://images.unsplash.com/photo-1511285560929-80b456fea0bc?auto=format&fit=crop&w=1200&q=80",alt:"Wedding reception tables"},
  {id:"3",src:"https://images.unsplash.com/photo-1606800052052-a08af7148866?auto=format&fit=crop&w=1200&q=80",alt:"Wedding rings and florals"},
  {id:"4",src:"https://images.unsplash.com/photo-1464366400600-7168b8af9bc3?auto=format&fit=crop&w=1200&q=80",alt:"Elegant wedding reception"}
];

export default function PhotoManagerPreview(){
 return <main className="container" style={{padding:"40px 20px 80px",maxWidth:1100}}>
  <div className="notice" style={{marginBottom:22}}><strong>Preview only · No vendor login required</strong><br/>This page demonstrates the new Main Profile Photo experience. Nothing you click here changes a real vendor profile.</div>
  <div style={{display:"flex",justifyContent:"space-between",gap:16,alignItems:"end",flexWrap:"wrap",marginBottom:22}}><div><span className="eyebrow">Vendor Portal · Photos</span><h1 style={{marginBottom:8}}>Choose your main profile photo</h1><p className="meta" style={{maxWidth:760,margin:0}}>Your main profile photo is the first image couples see across My Portland Wedding — including vendor cards, category pages, featured placements and Wedding Builder results.</p></div><Link className="btn light" href="/">← Back to MPW</Link></div>
  <section className="panel dashboardPanel" style={{marginBottom:22}}><div style={{display:"grid",gridTemplateColumns:"minmax(220px,360px) 1fr",gap:24,alignItems:"center"}}><div style={{position:"relative",borderRadius:18,overflow:"hidden",aspectRatio:"4 / 3"}}><img src={samplePhotos[0].src} alt={samplePhotos[0].alt} style={{width:"100%",height:"100%",objectFit:"cover",display:"block"}}/><span style={{position:"absolute",left:12,top:12,background:"#fff",padding:"7px 11px",borderRadius:999,fontWeight:800,fontSize:13}}>✓ Main Profile Photo</span></div><div><span className="eyebrow">Currently shown across MPW</span><h2 style={{margin:"6px 0 8px"}}>Your first impression</h2><p className="meta">Choose the image that best represents your business. You can change it anytime without deleting or re-uploading your gallery.</p><div className="notice success" style={{marginTop:14}}>This photo will be prioritized anywhere MPW displays one image for your business.</div></div></div></section>
  <section className="panel dashboardPanel"><div style={{display:"flex",justifyContent:"space-between",alignItems:"center",gap:12,flexWrap:"wrap"}}><div><h2 style={{marginBottom:5}}>Your photos</h2><p className="meta" style={{marginTop:0}}>Select any photo below to make it your main profile photo.</p></div><button className="btn primary" type="button">+ Upload Photo</button></div><div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(210px,1fr))",gap:16,marginTop:18}}>{samplePhotos.map((p,i)=><article key={p.id} style={{border:i===0?"2px solid #7c6651":"1px solid rgba(70,55,40,.18)",borderRadius:16,overflow:"hidden",background:"#fff",boxShadow:i===0?"0 8px 24px rgba(70,55,40,.12)":"none"}}><div style={{position:"relative",aspectRatio:"4 / 3"}}><img src={p.src} alt={p.alt} style={{width:"100%",height:"100%",objectFit:"cover",display:"block"}}/>{i===0&&<span style={{position:"absolute",left:10,top:10,background:"#fff",padding:"6px 9px",borderRadius:999,fontWeight:800,fontSize:12}}>✓ Main</span>}</div><div style={{padding:12}}>{i===0?<button className="btn light" type="button" disabled style={{width:"100%"}}>Current Main Photo</button>:<button className="btn primary" type="button" style={{width:"100%"}}>Set as Main Photo</button>}</div></article>)}</div></section>
 </main>
}
